"""Agglomerative clustering of the learned centroids + SSE elbow analysis.

Paper, Section 2.6: "first by applying agglomerative clustering on the
centroids, followed by constructing a dendrogram ... for a given number of
clusters k, the dendrogram is cut at a suitable height to obtain k clusters ...
we compute the fit of the data using the standard k-means sum of squares
formula SSE_k ... After computing SSE_k for every k, we construct the elbow plot
of SSE_k vs. k."
"""

from __future__ import annotations

import numpy as np
from sklearn.cluster import AgglomerativeClustering


def sse_k(labels: np.ndarray, points: np.ndarray) -> float:
    """SSE_k = sum_t sum_{i in C_t} ||u_i - mean(C_t)||^2  (paper, Section 2.6)."""
    labels = np.asarray(labels)
    total = 0.0
    for c in np.unique(labels):
        pts = points[labels == c]
        mu = pts.mean(axis=0)
        total += float(((pts - mu) ** 2).sum())
    return total


def sse_curve(centroids: np.ndarray, k_min: int = 1, k_max: int = 12,
              linkage: str = "ward") -> tuple[list[int], list[float]]:
    """SSE_k for k = k_min..k_max from agglomerative clustering of the centroids."""
    centroids = np.asarray(centroids, dtype=np.float64)
    n = centroids.shape[0]
    k_max = min(k_max, n)
    ks, vals = [], []
    for k in range(k_min, k_max + 1):
        if k == 1:
            labels = np.zeros(n, dtype=int)
        else:
            labels = AgglomerativeClustering(n_clusters=k,
                                             linkage=linkage).fit_predict(centroids)
        ks.append(k)
        vals.append(sse_k(labels, centroids))
    return ks, vals


def _normalise(v: np.ndarray) -> np.ndarray:
    v = np.asarray(v, dtype=np.float64)
    lo, hi = float(v.min()), float(v.max())
    if hi - lo < 1e-15:
        return np.zeros_like(v)
    return (v - lo) / (hi - lo)


def elbow_max_distance(ks, sse) -> int:
    """Kneedle-style elbow: point of maximum distance to the chord joining the
    endpoints of the normalised SSE_k curve (assumption A8)."""
    ks = np.asarray(ks, dtype=np.float64)
    sse = np.asarray(sse, dtype=np.float64)
    x = _normalise(ks)
    y = _normalise(sse)
    # SSE decreases with k, so the "corner" lies below the chord
    p0 = np.array([x[0], y[0]])
    p1 = np.array([x[-1], y[-1]])
    d = p1 - p0
    L = np.hypot(*d)
    if L < 1e-15:
        return int(ks[0])
    dist = np.abs(np.cross(d, np.stack([x, y], axis=1) - p0)) / L
    return int(ks[int(np.argmax(dist))])


def elbow_max_drop(ks, sse) -> int:
    """k with the largest single-step decrease in SSE_k."""
    ks = np.asarray(ks, dtype=np.float64)
    sse = np.asarray(sse, dtype=np.float64)
    if len(sse) < 2:
        return int(ks[0])
    return int(ks[int(np.argmax(np.diff(sse)))])


def elbow_second_difference(ks, sse) -> int:
    """k maximising the (negative) second difference of SSE_k."""
    ks = np.asarray(ks, dtype=np.float64)
    sse = np.asarray(sse, dtype=np.float64)
    if len(sse) < 3:
        return int(ks[0])
    return int(ks[1 + int(np.argmax(np.diff(sse, 2)))])


def select_k(centroids: np.ndarray, k_min: int = 2, k_max: int = 12,
             linkage: str = "ward") -> dict:
    """Full elbow analysis.  Returns labels at every k, the SSE curve and the
    elbow-selected number of clusters under three deterministic rules."""
    ks, sse = sse_curve(centroids, k_min=k_min, k_max=k_max, linkage=linkage)
    out = {
        "ks": ks,
        "sse": sse,
        "elbow_max_distance": elbow_max_distance(ks, sse),
        "elbow_max_drop": elbow_max_drop(ks, sse),
        "elbow_second_difference": elbow_second_difference(ks, sse),
    }
    out["elbow_k"] = out["elbow_max_distance"]
    return out


def labels_at_k(centroids: np.ndarray, k: int, linkage: str = "ward") -> np.ndarray:
    """Agglomerative clustering of the centroids cut at k clusters."""
    centroids = np.asarray(centroids, dtype=np.float64)
    if k <= 1:
        return np.zeros(centroids.shape[0], dtype=int)
    return AgglomerativeClustering(n_clusters=k,
                                   linkage=linkage).fit_predict(centroids)

